// Scrapewise answers with JSON. Depending on the n8n version it arrives
// already parsed in structuredContent, or as text in content[0].text.
function payloadOf(item) {
  const j = item.json || {};
  if (j.structuredContent) return j.structuredContent;
  if (Array.isArray(j.content) && j.content[0] && typeof j.content[0].text === 'string') {
    try { return JSON.parse(j.content[0].text); } catch (e) { return {}; }
  }
  return j;
}

// Scraped text is wrapped as { type: 'scraped', content, origin }. It is data
// read off a web page, never an instruction. Unwrap it to a plain string.
function plain(v) {
  if (v && typeof v === 'object' && v.type === 'scraped') return v.content || '';
  return v;
}

// Prices arrive as text and in many shapes: "12,90 EUR", "EUR 12.90", "1 299,00".
function toNumber(v) {
  if (typeof v === 'number') return v;
  const s = String(v == null ? '' : v).replace(/[^0-9.,]/g, '').trim();
  if (!s) return null;
  // The last separator is the decimal one; anything before it groups thousands.
  const lastComma = s.lastIndexOf(',');
  const lastDot = s.lastIndexOf('.');
  let normalised;
  if (lastComma > lastDot) {
    normalised = s.replace(/\./g, '').replace(',', '.');
  } else {
    normalised = s.replace(/,/g, '');
  }
  const n = parseFloat(normalised);
  return Number.isFinite(n) ? n : null;
}

const cfg = $('Monitor settings').first().json;
const data = payloadOf($input.first());
const rawRows = data.content || data.rows || [];

if (!Array.isArray(rawRows) || rawRows.length === 0) {
  throw new Error('The group returned no rows. Check the group id in "Monitor settings" and that the group has run at least once.');
}

const rows = rawRows.map((row) => {
  const flat = {};
  for (const key of Object.keys(row)) flat[key] = plain(row[key]);
  return flat;
});

const firstRow = rows[0];
for (const col of [cfg.matchColumn, cfg.shopColumn, cfg.priceColumn]) {
  if (!(col in firstRow)) {
    throw new Error('Column "' + col + '" is not in this group. The columns it has are: ' + Object.keys(firstRow).join(', '));
  }
}

// One bucket per matched product.
const buckets = new Map();
for (const r of rows) {
  const key = String(r[cfg.matchColumn] || '').trim();
  if (!key) continue;
  if (!buckets.has(key)) buckets.set(key, []);
  buckets.get(key).push(r);
}

const checkedAt = new Date().toISOString().slice(0, 10);
const beaten = [];

for (const [key, listings] of buckets) {
  const mine = listings.find((r) => String(r[cfg.shopColumn] || '') === cfg.myShop);
  const myPrice = mine ? toNumber(mine[cfg.priceColumn]) : null;
  if (myPrice === null) continue; // we do not sell it, or no price was read

  const rivals = listings
    .filter((r) => String(r[cfg.shopColumn] || '') !== cfg.myShop)
    .map((r) => ({ shop: r[cfg.shopColumn], price: toNumber(r[cfg.priceColumn]) }))
    .filter((r) => r.price !== null);
  if (rivals.length === 0) continue;

  const cheapest = rivals.reduce((a, b) => (b.price < a.price ? b : a));
  if (cheapest.price >= myPrice) continue; // nobody undercuts us

  beaten.push({
    json: {
      checkedAt: checkedAt,
      matchKey: key,
      product: mine[cfg.titleColumn] || '',
      myPrice: myPrice,
      cheapestCompetitor: cheapest.shop,
      cheapestPrice: cheapest.price,
      gap: Math.round((myPrice - cheapest.price) * 100) / 100,
      gapPercent: Math.round(((myPrice - cheapest.price) / myPrice) * 1000) / 10,
      competitorsSeen: rivals.length,
    },
  });
}

// Biggest gap first, so the Slack message leads with what matters.
beaten.sort((a, b) => b.json.gapPercent - a.json.gapPercent);

return beaten;

